export const getRecipeById = (id) => {
  return recipesDb.find(r => r.id === id) || recipesDb[0];
};

export const getRecipesByGoalAndMealType = (goal, mealType) => {
  return recipesDb.filter(r => r.goal.includes(goal) && r.mealType === mealType);
};
